import matplotlib.pyplot as plt

HEADERS = {
    'accept': 'application/json'
}

def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data: {e}")

    if not data:
        raise Exception("Empty data received from API.")

    try:
        if isinstance(data, list):
            df = pd.DataFrame(data)
        elif isinstance(data, dict):
            if 'data' in data:
                df = pd.DataFrame(data['data'])
            elif 'results' in data:
                df = pd.DataFrame(data['results'])
            else:
                df = pd.DataFrame([data])
        else:
            raise Exception("Invalid data format.")
    except Exception as e:
        raise Exception(f"Failed to convert data to DataFrame: {e}")

    if df.empty:
        raise Exception("DataFrame is empty after conversion.")

    numeric_cols = df.select_dtypes(include=['number']).columns
    if len(numeric_cols) < 2:
        raise Exception("Not enough numerical columns for correlation heatmap.")

    corr_matrix = df[numeric_cols].corr()
    fig, ax = plt.subplots(figsize=(10, 8))
    sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', ax=ax, fmt='.2f')
    ax.set_title('Correlation Heatmap')
    plt.tight_layout()
    plt.show()

    return (df, ax)
```

